-- Correct change-log identity: pendaftaran events use siswa_detail.pendaftaran_id, never siswa_id.
create or replace function public.integration_capture_change() returns trigger language plpgsql security definer set search_path=public as $$ declare v_new jsonb:=case when tg_op='DELETE' then '{}'::jsonb else to_jsonb(new) end; v_old jsonb:=case when tg_op='INSERT' then '{}'::jsonb else to_jsonb(old) end; v_id uuid; v_student uuid; v_class uuid; v_registration uuid; v_dept uuid; v_year uuid; v_prev_dept uuid; v_prev_year uuid; begin
if tg_table_name='siswa' then v_student:=coalesce((v_new->>'id')::uuid,(v_old->>'id')::uuid); select d.pendaftaran_id,d.tahun_ajaran_id into v_registration,v_year from public.siswa_detail d where d.siswa_id=v_student order by d.id limit 1; v_dept:=nullif(v_new->>'departemen_id','')::uuid; v_prev_dept:=nullif(v_old->>'departemen_id','')::uuid; if v_registration is not null then insert into public.integration_change_log(object_type,object_id,change_type,department_id,academic_year_id,previous_department_id) values('pendaftaran',v_registration,case when tg_op='DELETE' then 'delete' else 'upsert' end,v_dept,v_year,v_prev_dept); end if; if tg_op='DELETE' or coalesce(v_new->>'status','')<>'calon' then insert into public.integration_change_log(object_type,object_id,change_type,department_id,academic_year_id,previous_department_id) values('siswa',v_student,case when tg_op='DELETE' then 'delete' else 'upsert' end,v_dept,v_year,v_prev_dept); end if; return coalesce(new,old);
elsif tg_table_name='siswa_detail' then v_student:=coalesce(nullif(v_new->>'siswa_id','')::uuid,nullif(v_old->>'siswa_id','')::uuid); v_registration:=coalesce(nullif(v_new->>'pendaftaran_id','')::uuid,nullif(v_old->>'pendaftaran_id','')::uuid); select s.departemen_id into v_dept from public.siswa s where s.id=v_student; v_year:=nullif(v_new->>'tahun_ajaran_id','')::uuid; v_prev_year:=nullif(v_old->>'tahun_ajaran_id','')::uuid; if v_registration is not null then insert into public.integration_change_log(object_type,object_id,change_type,department_id,academic_year_id,previous_academic_year_id) values('pendaftaran',v_registration,case when tg_op='DELETE' then 'delete' else 'upsert' end,v_dept,v_year,v_prev_year); if v_new->'dokumen_kk_path' is distinct from v_old->'dokumen_kk_path' or v_new->'dokumen_akta_path' is distinct from v_old->'dokumen_akta_path' or v_new->'dokumen_rapor_path' is distinct from v_old->'dokumen_rapor_path' or v_new->'dokumen_ijazah_path' is distinct from v_old->'dokumen_ijazah_path' then insert into public.integration_change_log(object_type,object_id,change_type,department_id,academic_year_id) values('dokumen',v_registration,'upsert',v_dept,v_year); end if; end if; return coalesce(new,old);
elsif tg_table_name='kelas' then v_id:=coalesce((v_new->>'id')::uuid,(v_old->>'id')::uuid); v_dept:=nullif(v_new->>'departemen_id','')::uuid; v_prev_dept:=nullif(v_old->>'departemen_id','')::uuid; insert into public.integration_change_log(object_type,object_id,change_type,department_id,previous_department_id) values('kelas',v_id,case when tg_op='DELETE' then 'delete' else 'upsert' end,v_dept,v_prev_dept); return coalesce(new,old);
elsif tg_table_name='kelas_siswa' then v_student:=coalesce(nullif(v_new->>'siswa_id','')::uuid,nullif(v_old->>'siswa_id','')::uuid); v_class:=coalesce(nullif(v_new->>'kelas_id','')::uuid,nullif(v_old->>'kelas_id','')::uuid); v_year:=nullif(v_new->>'tahun_ajaran_id','')::uuid; v_prev_year:=nullif(v_old->>'tahun_ajaran_id','')::uuid; if v_student is not null then select s.departemen_id into v_dept from public.siswa s where s.id=v_student; insert into public.integration_change_log(object_type,object_id,change_type,department_id,academic_year_id,previous_academic_year_id) values('siswa',v_student,'upsert',v_dept,v_year,v_prev_year); end if; if v_class is not null then select k.departemen_id into v_dept from public.kelas k where k.id=v_class; insert into public.integration_change_log(object_type,object_id,change_type,department_id,academic_year_id,previous_academic_year_id) values('kelas',v_class,'upsert',v_dept,v_year,v_prev_year); end if; return coalesce(new,old); end if; return coalesce(new,old); end $$;